'use strict';
let creatorSelectedShop=localStorage.getItem('jioflow.creator.selectedShop')||'',shopsExpanded=false,platformDetail='orders',platformPeopleType='Owner',chartSource='All';
function businessStores(){return authDirectory.stores.filter(s=>!s.platform)}
function ownerBusiness(){const a=accountRecord();return businessStores().find(s=>s.owner===a?.id&&(s.id===a.businessId||s.id===a.storeId))||businessStores().find(s=>s.owner===a?.id)}
ownedShops=function(){const shop=ownerBusiness();return shop?[shop]:[]};
function chooseBusiness(id){if(!isCreator())return toast('Only Creator can switch businesses.');if(id!=='all'&&!businessStores().some(s=>s.id===id&&s.active))return;const previousPage=page;creatorSelectedShop=id;localStorage.setItem('jioflow.creator.selectedShop',id);if(id!=='all'){loadStore(id);sessionAccount.storeId=id;}selected.clear();cart=[];chartSource='All';query='';subtab='All';tagFilter='';pageNo=1;window.callFilter='';window.responseFilter='';window.funnelFilter='';window.customerSource='';reportAgentId='';reportPage=1;reportSearch='';page=previousPage==='agentdetail'?'agentreports':previousPage;closeModal();render()}

creatorOpenShop=chooseBusiness;
