function platformDetailMetric(data,type){const orders=data.orders.filter(inRange),confirmed=orders.filter(o=>['Confirmed','Confirm',data.settings.confirmStatus].filter(Boolean).includes(o.status));if(type==='confirmed')return confirmed.length;if(type==='completed')return completedProfileSet(data.customers).length;if(type==='customers')return data.customers.length;if(type==='revenue')return money(sumBy(confirmed,orderTotal));if(type==='delivered'||type==='returned')return orders.filter(o=>o.shipment===(type==='delivered'?'Delivered':'Returned')).length;if(type==='profit'){let total=0;for(const o of confirmed){const costs=o.items.map(x=>x.cost??data.products.find(p=>p.id===x.product)?.cost);if(costs.some(x=>x==null))return 'Cost missing';total+=orderTotal(o)-sumBy(o.items,x=>x.qty*(x.cost??data.products.find(p=>p.id===x.product)?.cost??0))-Number(o.finance?.courierCost??o.delivery)-Number(o.finance?.codFee||0)-Number(o.finance?.packaging||0)-Number(o.finance?.returnFee||0)}return money(total)}return orders.length}
platformDetailView=function(){if(!isCreator())return empty('Creator access only.');return heading('Business details · '+platformDetail,'Selected reporting period. Open a business for its individual records.',`<button onclick="nav('creator')">Back to dashboard</button>`)+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Business</th><th>${esc(platformDetail)}</th><th></th></tr></thead><tbody>${platformShopRows().map(({s,data})=>`<tr><td>${esc(s.name)}</td><td><strong>${esc(platformDetailMetric(data,platformDetail))}</strong></td><td><button onclick="openBusinessMetric('${s.id}','${platformDetail}')">View matching records</button></td></tr>`).join('')||'<tr><td colspan="3">No shops yet.</td></tr>'}</tbody></table></div></section>`};
function openBusinessMetric(id,type){if(!isCreator())return;chooseBusiness(id);if(['confirmed','delivered','returned'].includes(type))dashboardOrders({confirmed:'Confirmed',delivered:'Delivered',returned:'Returned'}[type]);else if(type==='profit')nav('profit');else if(type==='customers'||type==='completed'){nav('customers');if(type==='completed')selectFollowOverview('completed')}else nav('orders')}
