function platformSummaryComparison(label){const current=platformMetrics(),bounds=rangeBounds();if(!Number.isFinite(bounds.start)||!Number.isFinite(bounds.end))return {current:null,previous:null,kind:'lifetime'};const old=platformShopRows().flatMap(({s,data})=>data.orders.filter(o=>{const at=new Date(o.created).getTime();return at>=bounds.start-(bounds.end-bounds.start)&&at<bounds.start}).map(o=>({...o,shopId:s.id,status:['Confirmed','Confirm',data.settings.confirmStatus].filter(Boolean).includes(o.status)?'Confirmed':o.status}))),oldConfirmed=old.filter(o=>o.status==='Confirmed'),key=label.toLowerCase();if(key==='confirmed orders')return {current:current.confirmed.length,previous:oldConfirmed.length,kind:'count'};if(key==='all orders')return {current:current.orders.length,previous:old.length,kind:'count'};if(key==='revenue')return {current:current.revenue,previous:sumBy(oldConfirmed,orderTotal),kind:'money'};if(['delivered','returned'].includes(key)){const status=key==='delivered'?'Delivered':'Returned';return {current:current.orders.filter(o=>o.shipment===status).length,previous:old.filter(o=>o.shipment===status).length,kind:'count'}}return {current:null,previous:null,kind:'snapshot'}}
const balancedSummaryRender=render;
render=function(){balancedSummaryRender();if(!signedIn||!sessionAllowed())return;$('#view')?.querySelectorAll('.insight-tile,.overview-tile').forEach(el=>{const row=el.querySelector('.metric-value-row');if(!row||el.querySelector('.metric-indicators'))return;const label=el.querySelector('.tile-label,.label')?.textContent?.replace('↗','').trim()||'',icon=el.querySelector('.metric-icon'),badge=el.querySelector('.change-badge'),indicators=document.createElement('div');indicators.className='metric-indicators';row.classList.add('metric-balanced');if(icon)indicators.append(icon);if(page==='creator'){const d=platformSummaryComparison(label),v=metricComparisonText(label,d),change=badge||document.createElement('span');change.className='change-badge quality-'+v.quality;change.textContent=v.badge;indicators.append(change);const previous=document.createElement('small');previous.className='previous-line';previous.innerHTML='Previous: <b>'+esc(String(v.previous))+'</b>'+(d.previous!=null&&d.current!=null?` <span class="comparison-meaning quality-${v.quality}">${esc(v.meaning)}</span>`:'');row.after(previous)}else if(badge)indicators.append(badge);else{const hint=el.querySelector('.metric-context,small')?.textContent||'',match=hint.match(/\d+(?:\.\d+)?%/),change=document.createElement('span');change.className='change-badge';change.textContent=match?match[0]:'—';change.title=match?'Share of current total':'No comparison baseline';indicators.append(change)}row.append(indicators)})};

